$path = Join-Path $PSScriptRoot '..\admin-panel\app\islamic-lifestyle\page.tsx'
$content = [IO.File]::ReadAllText((Resolve-Path $path), [Text.Encoding]::UTF8)
$oldFunction = ' const selectLanguage=(code:string)=>{if(code!=="en"&&!form.id){setMessage("First save this item in English. Then choose another language.");return}setLanguage(code);if(form.id){const item=items.find(x=>x.id===form.id);if(item)setForm(localizedForm(item,code))}setMessage(code==="en"?"Editing the English base content.":itemLanguageMessage(code))};'
$newFunction = ' const selectLanguage=(code:string)=>{setLanguage(code);if(form.id){const item=items.find(x=>x.id===form.id);if(item)setForm(localizedForm(item,code));setMessage(code==="en"?"Editing the English base content.":itemLanguageMessage(code));return}setMessage(code==="en"?"Create new English base content below.":"Language selected. Now choose an existing category or chapter to translate.")}; const chooseTranslationItem=(id:string)=>{const item=items.find(x=>x.id===id);if(!item)return;setForm(localizedForm(item,language));setMessage(item.translations?.[language]?`Editing saved ${languages.find(x=>x.code===language)?.label||language} translation.`:`Add ${languages.find(x=>x.code===language)?.label||language} translation for ${item.title}.`);requestAnimationFrame(()=>formRef.current?.scrollIntoView({behavior:"smooth",block:"start"}))};'
if (-not $content.Contains($oldFunction)) { throw 'selectLanguage anchor not found' }
$content = $content.Replace($oldFunction,$newFunction)
$oldControls = '<div className="languageControls single"><label><span>Select content language</span><select aria-label="Select content language" value={language} onChange={e=>selectLanguage(e.target.value)}><option value="en">English (Base)</option>{languages.filter(x=>x.code!=="en").map(x=><option key={x.code} value={x.code}>{x.label} ({x.code.toUpperCase()}){form.id&&items.find(item=>item.id===form.id)?.translations?.[x.code]?" - Saved":""}</option>)}</select><small>Click to choose from all 195 languages. You can type the first letters while the list is open.</small></label></div>'
$newControls = '<div className="languageControls single"><label><span>Select content language</span><select aria-label="Select content language" value={language} onChange={e=>selectLanguage(e.target.value)}><option value="en">English (Base)</option>{languages.filter(x=>x.code!=="en").map(x=><option key={x.code} value={x.code}>{x.label} ({x.code.toUpperCase()}){form.id&&items.find(item=>item.id===form.id)?.translations?.[x.code]?" - Saved":""}</option>)}</select><small>Click to choose from all 195 languages.</small></label>{language!=="en"&&<label><span>Choose category or chapter to translate</span><select aria-label="Choose content to translate" value={form.id} onChange={e=>chooseTranslationItem(e.target.value)}><option value="">Select existing content...</option><optgroup label="Lifestyle categories">{items.filter(x=>x.kind==="category").map(x=><option key={x.id} value={x.id}>{x.title}{x.translations?.[language]?" - Translation saved":""}</option>)}</optgroup><optgroup label="Chapters">{items.filter(x=>x.kind==="chapter").map(x=><option key={x.id} value={x.id}>{String(x.order||1).padStart(2,"0")} - {x.title}{x.translations?.[language]?" - Translation saved":""}</option>)}</optgroup></select><small>Select the English item that this translation belongs to.</small></label>}</div>'
if (-not $content.Contains($oldControls)) { throw 'languageControls anchor not found' }
$content = $content.Replace($oldControls,$newControls)
[IO.File]::WriteAllText((Resolve-Path $path), $content, [Text.UTF8Encoding]::new($false))
